-- T0B-13.C15 schema suite: payments catalogue properties (C15 05-SCHEMA §1, §3, §4, §5, §6, §8; AC-0B-2.1, 2.2, 2.3, 2.4, 3.6, 4.1, 4.2, 4.3, 5.1, 5.3, 6.1, 6.2, 6.3).
-- Pure pg_catalog assertions: no fixtures, no data written. One rolled-back transaction. RLS is never disabled.
-- Run from the repo root: pg_prove -d <db> db/tests/payments/T0B-13.C15_schema.test.sql   (pgTAP in schema `extensions`; migrations + seeds loaded; superuser)
-- Markers (the node test checks them): C15 check 1 inventory/owner/no sequences, enums or views, 2 RLS ENABLE+FORCE (G exempt), 3 policy set per table (30 tenant + 1 owner, no DELETE policy, staff guard), 4 grant matrix (no DELETE anywhere),
-- 5 indexes + constraint names + FKs, 6 triggers + functions (2 INVOKER guards, 1 DEFINER with EXECUTE for lims_api only) + audit, 7 FK direction + DEFINER inventory + seeds (AC-0B-6.1 / 6.2 / 6.3). Check 8 and "C15 test 1-14" (05-SCHEMA §10) are in T0B-13.C15_behaviour.test.sql.
-- Scope note: event_inbox is C0's (T0B-05) and is excluded from every count. lims_api / lims_worker INHERIT lims_app, so "no DELETE / no UPDATE" is asserted for lims_app only.
-- Tester assumption (see note T0B-13.C15-tests.md): audit trigger on every class M / C table (8), none on class A (3) or G (1) - 05-SCHEMA §1 "Audited".
BEGIN;
SET search_path = extensions, public, pg_catalog;
SELECT * FROM no_plan();

-- t: table; cls: §1 class; u: lims_app UPDATE grant; npol: expected policies; aud: audit trigger expected
CREATE TEMP TABLE rt(t, cls, u, npol, aud) AS VALUES
  ('settings','M',true,3,true),('merchant_accounts','M',true,3,true),('intents','C',true,3,true),('intent_transitions','A',false,2,false),('gateway_calls','A',false,2,false),('callbacks','A',false,2,false),
  ('refunds','C',true,3,true),('reconciliation_runs','C',true,3,true),('reconciliation_findings','C',true,3,true),('static_qr_reconciliations','C',true,3,true),('cs_reasons','M',true,3,true);
CREATE TEMP TABLE rg(t) AS VALUES ('g_cs_reasons');
CREATE TEMP TABLE rf(f) AS VALUES ('intents_transition_guard'),('refunds_transition_guard');

-- C15 check 1: inventory, owner (AC-0B-1.2, AC-0B-6.3), schema privileges, no sequences / enums / views (§7)
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'payments'::regnamespace AND c.relkind IN ('r','p')), 11 + 1 + 1, 'C15 check 1: payments holds 11 tenant + 1 G table + event_inbox (12 chunk tables + inbox)');
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'payments'::regnamespace AND c.relkind IN ('v','m')), 0, 'C15 check 1 / §7: no view and no materialized view (C15 publishes none)');
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'payments'::regnamespace AND c.relkind = 'S'), 0, 'C15 check 1: no sequences');
SELECT is((SELECT count(*)::int FROM pg_type t WHERE t.typnamespace = 'payments'::regnamespace AND t.typtype = 'e'), 0, 'C15 check 1: no ENUM types');
SELECT is(pg_get_userbyid(c.relowner), 'lims_owner', 'C15 check 1: payments.' || c.relname || ' owned by lims_owner (AC-0B-1.2, AC-0B-6.3)') FROM pg_class c WHERE c.relnamespace = 'payments'::regnamespace AND c.relkind = 'r';
SELECT is(has_schema_privilege('lims_app', 'payments', 'USAGE'), true, 'lims_app has USAGE on schema payments');
SELECT is(has_schema_privilege(r, 'payments', 'CREATE'), false, r || ' cannot CREATE in payments') FROM unnest(ARRAY['lims_app','lims_api','lims_worker','lims_analytics']) r;
SELECT is((SELECT count(*)::int FROM rt) + (SELECT count(*)::int FROM rg), 12, 'C15 check 1: 12 tables in the inventory (= table count of the 05-SCHEMA §6 DDL)');
SELECT is((SELECT array_agg(relname::text ORDER BY relname) FROM pg_class WHERE relnamespace = 'payments'::regnamespace AND relkind = 'r' AND relname <> 'event_inbox'), (SELECT array_agg(t ORDER BY t) FROM (SELECT t FROM rt UNION ALL SELECT t FROM rg) x), 'C15 check 1: the table set equals the §1 inventory');

-- C15 check 2: RLS ENABLE + FORCE on the 11 tenant tables, none on the G table (AC-0B-2.1, 2.4)
SELECT is((SELECT relrowsecurity AND relforcerowsecurity FROM pg_class WHERE oid = ('payments.' || t)::regclass), true, 'C15 check 2 / AC-0B-2.1: ENABLE + FORCE RLS on payments.' || t) FROM rt;
SELECT is((SELECT relrowsecurity OR relforcerowsecurity FROM pg_class WHERE oid = ('payments.' || t)::regclass), false, 'C15 check 2 / AC-0B-2.1: payments.' || t || ' is RLS-exempt (global coded set, listed in rls_exempt.txt)') FROM rg;
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'payments' AND tablename = g.t), 0, 'C15 check 2: no policy on ' || g.t) FROM rg g;
SELECT is(NOT EXISTS (SELECT 1 FROM pg_class WHERE relnamespace = 'payments'::regnamespace AND relkind = 'r' AND relname <> 'event_inbox' AND relname NOT LIKE 'g\_%' AND NOT (relrowsecurity AND relforcerowsecurity)), true, 'C15 check 2 / AC-0B-2.2 / AC-0B-2.4: no payments tenant table without FORCE RLS (RLS is never off)');
SELECT is((SELECT count(*)::int FROM information_schema.columns WHERE table_schema = 'payments' AND column_name = 'tenant_id' AND is_nullable = 'YES'), 0, 'C15 check 2 / AC-0B-3.5: tenant_id is NOT NULL everywhere');

-- C15 check 3: policy set per table (AC-0B-2.3): 30 tenant policies TO lims_app (SELECT + INSERT, + UPDATE except class A) + the P-41 owner policy; staff guard (P-16); no centre clause; no DELETE policy (§3, §6)
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'payments' AND tablename = rt.t AND roles = ARRAY['lims_app']::name[]), npol, 'C15 check 3 / AC-0B-2.3: payments.' || t || ' has ' || npol || ' lims_app policies') FROM rt;
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'payments' AND tablename <> 'event_inbox'), 31, 'C15 check 3: 31 policies in payments (ex event_inbox): 30 tenant + 1 owner');
SELECT is((SELECT array_agg(policyname::text ORDER BY policyname::text) FROM pg_policies WHERE schemaname = 'payments' AND tablename <> 'event_inbox' AND roles <> ARRAY['lims_app']::name[]), ARRAY['intents__select__owner_only'], 'C15 check 3 / P-41 (b): the only policy not TO lims_app is intents__select__owner_only');
SELECT is((SELECT roles FROM pg_policies WHERE schemaname = 'payments' AND policyname = 'intents__select__owner_only'), ARRAY['lims_owner']::name[], 'C15 check 3 / P-41 (b): the owner policy is TO lims_owner only (a lims_api session that sets the GUC itself sees nothing)');
SELECT is((SELECT cmd FROM pg_policies WHERE schemaname = 'payments' AND policyname = 'intents__select__owner_only'), 'SELECT', 'C15 check 3: owner policy is FOR SELECT');
SELECT matches((SELECT qual FROM pg_policies WHERE schemaname = 'payments' AND policyname = 'intents__select__owner_only'), 'callback_token_sha256 = decode\(current_setting\(''app\.pre_payments_callback_token_sha256''::text, true\), ''hex''::text\)', 'C15 check 3 / P-41 (b): owner policy USING = decode(current_setting(GUC)) on the token hash');
-- LD-230 (3): pgTAP has no like()/unlike(); matches()/doesnt_match() with the anchored regex of the same LIKE pattern (% -> .*, _ -> .)
SELECT doesnt_match((SELECT qual FROM pg_policies WHERE schemaname = 'payments' AND policyname = 'intents__select__owner_only'), '^.* OR .*$', 'C15 check 3 / review m#14: no other disjunct in the owner policy');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'payments' AND tablename = rt.t AND cmd = 'UPDATE'), CASE WHEN u THEN 1 ELSE 0 END, 'C15 check 3: UPDATE policy on payments.' || t || ' iff a lims_app UPDATE grant exists (class A tables: none)') FROM rt;
-- T0B-GREEN-1 STALE: migration 20261105001000 (core__create_event_inboxes) adds event_inbox__delete__owner_only to every schema's event_inbox (purge by lims_owner); the check keeps its meaning for every money table and pins the inbox policy to lims_owner
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'payments' AND tablename <> 'event_inbox' AND cmd = 'DELETE'), 0, 'C15 check 3 / §3: no DELETE policy on any payments table (money records)');
SELECT is((SELECT array_agg(policyname::text || '|' || roles::text) FROM pg_policies WHERE schemaname = 'payments' AND tablename = 'event_inbox' AND cmd = 'DELETE'), ARRAY['event_inbox__delete__owner_only|{lims_owner}'], 'C15 check 3 / T0B-GREEN-1: the only DELETE policy of the schema is the event_inbox owner-only purge policy, TO lims_owner only');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'payments' AND tablename <> 'event_inbox' AND roles = ARRAY['lims_app']::name[] AND NOT (coalesce(qual, '') || coalesce(with_check, '')) LIKE '%is_staff_or_system%'), 0, 'C15 check 3 / P-16: staff-actor guard in every payments tenant policy (gate 9)');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'payments' AND tablename <> 'event_inbox' AND roles = ARRAY['lims_app']::name[] AND NOT (coalesce(qual, '') || coalesce(with_check, '')) LIKE '%current_tenant_id%'), 0, 'C15 check 3: tenant predicate in every tenant policy');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'payments' AND tablename <> 'event_inbox' AND (coalesce(qual, '') || coalesce(with_check, '')) ~ '(current_centre_ids|has_all_centres|current_partner_id|current_patient_id)'), 0, 'C15 check 3 / §3: no centre clause and no partner / patient scope in any payments policy (tenant scope; centre authorisation is in the API)');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'payments' AND tablename <> 'event_inbox' AND (coalesce(qual, '') || coalesce(with_check, '')) ~ '(device|patient|portal|partner)'), 0, 'C15 check 3 / 08 A17 P-16: no policy names a non-staff actor');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'payments' AND tablename <> 'event_inbox' AND roles = ARRAY['lims_app']::name[] AND policyname !~ ('^' || tablename || '__(select|insert|update)__tenant$')), 0, 'C15 check 3: policy names are <table>__<cmd>__tenant');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'payments' AND tablename <> 'event_inbox' AND policyname LIKE '%\_\_tenant\_centre'), 0, 'C15 check 3: no tenant_centre policy (the 08 A16.1 ::uuid[] cast has no occurrence in this schema)');

-- C15 check 4: grant matrix (AC-0B-4.2 / 4.3; §3): INSERT everywhere, UPDATE only on the 8 mutable tables, DELETE nowhere (§10 test 1)
SELECT is(has_table_privilege('lims_app', 'payments.' || t, 'SELECT'), true, 'C15 check 4: lims_app SELECT on payments.' || t) FROM rt;
SELECT is(has_table_privilege('lims_app', 'payments.' || t, 'INSERT'), true, 'C15 check 4 / AC-0B-4.2: lims_app INSERT on payments.' || t) FROM rt;
SELECT is(has_table_privilege('lims_app', 'payments.' || t, 'UPDATE'), u, 'C15 check 4 / AC-0B-4.1 / AC-0B-4.3: lims_app UPDATE on payments.' || t || ' (none on intent_transitions, gateway_calls, callbacks)') FROM rt;
SELECT is(has_table_privilege('lims_app', 'payments.' || t, 'DELETE'), false, 'C15 check 4 / AC-0B-4.2 / §10 test 1: lims_app has no DELETE on payments.' || t) FROM (SELECT t FROM rt UNION ALL SELECT t FROM rg) x(t);
SELECT is(has_table_privilege('lims_app', 'payments.' || t, 'TRUNCATE') OR has_table_privilege('lims_app', 'payments.' || t, 'REFERENCES') OR has_table_privilege('lims_app', 'payments.' || t, 'TRIGGER'), false, 'C15 check 4: no TRUNCATE / REFERENCES / TRIGGER on payments.' || t) FROM rt;
SELECT is(ARRAY[has_table_privilege('lims_app', 'payments.' || t, 'SELECT'), has_table_privilege('lims_app', 'payments.' || t, 'INSERT'), has_table_privilege('lims_app', 'payments.' || t, 'UPDATE'), has_table_privilege('lims_app', 'payments.' || t, 'DELETE')], ARRAY[true, false, false, false], 'C15 check 4: lims_app only SELECTs ' || t) FROM rg;
SELECT is(has_table_privilege('lims_analytics', 'payments.' || x.t, p), false, 'C15 check 4: lims_analytics has no ' || p || ' on payments.' || x.t) FROM (SELECT t FROM rt UNION ALL SELECT t FROM rg) x, unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE']) p;
SELECT is((SELECT count(*)::int FROM information_schema.role_table_grants WHERE table_schema = 'payments' AND grantee IN ('PUBLIC','anon','authenticated','service_role')), 0, 'C15 check 4: nothing granted to PUBLIC / anon / authenticated / service_role');

-- C15 check 5: indexes (§4) and constraint names / FKs: tenant_id leads every index except the documented callback-token one; the 24 named indexes exist; every __p_ index is partial; UNIQUE (tenant_id, id) on 10 tenant tables; tenant FK on all 11; composite FKs
SELECT is((regexp_match(pg_get_indexdef(i.indexrelid), '\(([^,)]+)'))[1], CASE WHEN c.relname = 'intents__callback_token_sha256__uq' THEN 'callback_token_sha256' ELSE 'tenant_id' END, 'C15 check 5: index ' || c.relname || ' leads with tenant_id (documented exception: intents__callback_token_sha256__uq, CR-C15-004)')
  FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_class t ON t.oid = i.indrelid
  WHERE t.relnamespace = 'payments'::regnamespace AND t.relname NOT LIKE 'g\_%' AND t.relname <> 'event_inbox' AND NOT i.indisprimary;
SELECT is((SELECT count(*)::int FROM pg_indexes WHERE schemaname = 'payments' AND indexname = n), 1, 'C15 check 5: index ' || n || ' exists (§4 / §6)')
  FROM unnest(ARRAY['intents__tenant_id_order_id__open__p_uq','intents__tenant_id_idempotency_key__uq','intents__tenant_id_gateway_txn__p_uq','intents__callback_token_sha256__uq','intents__tenant_id_callback_token__idx','intents__tenant_id_status_created__p_idx',
  'intents__tenant_id_settled__p_idx','intents__tenant_id_closed__p_idx','intents__tenant_id_created__idx','intents__tenant_id_order__idx','intent_transitions__tenant_id_intent__idx','gateway_calls__tenant_id_intent__idx','gateway_calls__tenant_id_refund__p_idx',
  'callbacks__tenant_id_intent__idx','refunds__tenant_id_intent_inflight__p_uq','refunds__tenant_id_idempotency_key__uq','refunds__tenant_id_status_created__idx','refunds__tenant_id_intent__idx','reconciliation_runs__tenant_id_running__p_uq',
  'reconciliation_runs__tenant_id_date__idx','reconciliation_findings__tenant_id_status__idx','reconciliation_findings__tenant_id_run__idx','static_qr__tenant_id_date_centre__p_uq','static_qr__tenant_id_date_all__p_uq']) n;
SELECT is((SELECT count(*)::int FROM pg_indexes WHERE schemaname = 'payments' AND tablename <> 'event_inbox' AND indexname NOT IN (SELECT conname FROM pg_constraint WHERE connamespace = 'payments'::regnamespace)), 24, 'C15 check 5: exactly the 24 spec indexes beyond the constraint-backed ones (no extra index)');
SELECT is((SELECT count(*)::int FROM pg_indexes WHERE schemaname = 'payments' AND indexname ~ '__p_(uq|idx)$' AND indexdef NOT LIKE '% WHERE %'), 0, 'C15 check 5: every __p_ index is partial');
SELECT is((SELECT count(*)::int FROM pg_indexes WHERE schemaname = 'payments' AND indexname IN ('intents__tenant_id_order_id__open__p_uq','intents__tenant_id_idempotency_key__uq','intents__tenant_id_gateway_txn__p_uq','intents__callback_token_sha256__uq','refunds__tenant_id_intent_inflight__p_uq','refunds__tenant_id_idempotency_key__uq','reconciliation_runs__tenant_id_running__p_uq','static_qr__tenant_id_date_centre__p_uq','static_qr__tenant_id_date_all__p_uq') AND indexdef LIKE 'CREATE UNIQUE INDEX%'), 9, 'C15 check 5: the 9 documented unique indexes are UNIQUE');
SELECT is((SELECT count(*)::int FROM pg_constraint WHERE conrelid = ('payments.' || t)::regclass AND contype = 'u' AND pg_get_constraintdef(oid) = 'UNIQUE (tenant_id, id)'), 1, 'C15 check 5 / 04 D8: UNIQUE (tenant_id, id) on payments.' || t) FROM rt WHERE t <> 'settings';
SELECT is((SELECT count(*)::int FROM pg_constraint WHERE conrelid = 'payments.settings'::regclass AND contype = 'p' AND pg_get_constraintdef(oid) = 'PRIMARY KEY (tenant_id)'), 1, 'C15 check 5 / §1 P-18(b): settings PRIMARY KEY (tenant_id), no id');
SELECT is((SELECT count(*)::int FROM pg_attribute WHERE attrelid = 'payments.settings'::regclass AND attname = 'id' AND NOT attisdropped), 0, 'C15 check 5 / §1: payments.settings has no id column');
SELECT is((SELECT count(*)::int FROM pg_constraint WHERE conrelid = ('payments.' || t)::regclass AND contype = 'f' AND confrelid = 'core.tenants'::regclass AND pg_get_constraintdef(oid) = 'FOREIGN KEY (tenant_id) REFERENCES core.tenants(id)'), 1, 'C15 check 5 / C0 §9 rule 1: tenant FK -> core.tenants on payments.' || t) FROM rt;
SELECT is((SELECT count(*)::int FROM pg_constraint c WHERE c.contype = 'f' AND c.conrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'payments'::regnamespace AND relname NOT LIKE 'g\_%' AND relname <> 'event_inbox')
  AND cardinality(c.conkey) = 1 AND c.confrelid <> 'core.tenants'::regclass AND c.confrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace = 'payments'::regnamespace AND relname LIKE 'g\_%')), 0, 'C15 check 5: every FK except the tenant FK is composite (tenant_id, x) (02-CV §5.4)');
SELECT is((SELECT count(*)::int FROM pg_constraint WHERE connamespace = 'payments'::regnamespace AND conname IN ('gateway_calls__refund__fk','gateway_calls__merchant__fk') AND contype = 'f' AND cardinality(conkey) = 2), 2, 'C15 check 5 / §10 test 10: gateway_calls -> refunds / merchant_accounts are composite (tenant_id, id) FKs');
SELECT is((SELECT count(*)::int FROM pg_constraint WHERE connamespace = 'payments'::regnamespace AND conname IN ('intents__idem__ck','refunds__idem__ck','callbacks__no_mobile__ck','refunds__held__ck','intents__settled__ck','intents__refunded__ck','intents__khalti_min__ck','merchant_accounts__fonepay_off__ck','merchant_accounts__secret_shape__ck','static_qr__status__ck') AND contype = 'c'), 10, 'C15 check 5: the named CHECKs of §10 tests 7-9 and the money invariants exist');
SELECT matches((SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conname = 'intents__idem__ck' AND conrelid = 'payments.intents'::regclass), '\{1,200\}', 'C15 check 5 / 08 A19 P-40: the port-key grammar caps the key at 200 characters');
SELECT is((SELECT attgenerated FROM pg_attribute WHERE attrelid = 'payments.static_qr_reconciliations'::regclass AND attname = 'difference_paisa'), 's', 'C15 check 5: static_qr_reconciliations.difference_paisa is a STORED generated column');

-- C15 check 6: triggers, functions, audit (AC-0B-4.1, 5.1, 5.3): 6 spec triggers, 2 INVOKER guard functions, 1 DEFINER (EXECUTE for lims_api only), 8 audit triggers
SELECT is((SELECT count(*)::int FROM pg_trigger tg WHERE tg.tgrelid = ('payments.' || t)::regclass AND NOT tg.tgisinternal AND tg.tgname = t || '__audit'), CASE WHEN aud THEN 1 ELSE 0 END, 'C15 check 6 / AC-0B-5.1: audit trigger on payments.' || t || ' iff class M / C') FROM rt;
SELECT is((SELECT count(*)::int FROM pg_trigger tg WHERE tg.tgrelid = ('payments.' || t)::regclass AND tg.tgname = t || '__audit' AND tg.tgfoid = 'app.tg_row_audit'::regproc), CASE WHEN aud THEN 1 ELSE 0 END, 'C15 check 6: audit trigger of payments.' || t || ' runs app.tg_row_audit') FROM rt;
SELECT is((SELECT count(*)::int FROM pg_trigger tg WHERE tg.tgrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'payments'::regnamespace) AND NOT tg.tgisinternal AND tg.tgname LIKE '%\_\_audit'), 8, 'C15 check 6 / AC-0B-5.3: 8 audit triggers (3 class M + 5 class C); none on the class-A tables or the G table');
SELECT matches((SELECT pg_get_triggerdef(oid) FROM pg_trigger WHERE tgrelid = 'payments.merchant_accounts'::regclass AND tgname = 'merchant_accounts__audit'), 'secret_ciphertext.*secret_nonce.*secret_auth_tag', 'C15 check 6 / CR-C15-013: the merchant_accounts audit trigger excludes the three secret columns');
SELECT is((SELECT array_agg(tgname::text ORDER BY tgname::text) FROM pg_trigger WHERE tgrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'payments'::regnamespace) AND NOT tgisinternal AND tgname NOT LIKE '%\_\_audit' AND tgname NOT LIKE '%event_inbox%'),
  ARRAY['intents__mutable_columns','intents__transition_guard','reconciliation_findings__mutable_columns','refunds__mutable_columns','refunds__transition_guard','static_qr__mutable_columns'], 'C15 check 6: exactly the 6 spec triggers by name');
SELECT is((SELECT count(*)::int FROM pg_trigger WHERE tgrelid = ('payments.' || x.t)::regclass AND tgname = x.n AND tgfoid = 'app.enforce_mutable_columns'::regproc AND (tgtype & 2) = 2 AND (tgtype & 16) = 16 AND (tgtype & 1) = 1), 1, 'C15 check 6 / §6: ' || x.n || ' is BEFORE UPDATE FOR EACH ROW via app.enforce_mutable_columns')
  FROM (VALUES ('intents','intents__mutable_columns'),('refunds','refunds__mutable_columns'),('reconciliation_findings','reconciliation_findings__mutable_columns'),('static_qr_reconciliations','static_qr__mutable_columns')) x(t, n);
SELECT is((SELECT count(*)::int FROM pg_trigger WHERE tgrelid = ('payments.' || x.t)::regclass AND tgname = x.n AND tgfoid = ('payments.' || x.f)::regproc AND (tgtype & 2) = 2 AND (tgtype & 16) = 16 AND (tgtype & 1) = 1), 1, 'C15 check 6 / §10 tests 4-5: ' || x.n || ' is BEFORE UPDATE FOR EACH ROW')
  FROM (VALUES ('intents','intents__transition_guard','intents_transition_guard'),('refunds','refunds__transition_guard','refunds_transition_guard')) x(t, n, f);
SELECT is((SELECT count(*)::int FROM pg_proc p WHERE p.pronamespace = 'payments'::regnamespace AND p.proname = f), 1, 'C15 check 6: payments.' || f || '() exists') FROM rf;
SELECT is((SELECT prosecdef FROM pg_proc WHERE pronamespace = 'payments'::regnamespace AND proname = f), false, 'C15 check 6 / AC-0B-4.1 / 04 D7: payments.' || f || ' is SECURITY INVOKER (no inventory row)') FROM rf;
SELECT is((SELECT proconfig FROM pg_proc WHERE pronamespace = 'payments'::regnamespace AND proname = f), ARRAY['search_path=""'], 'C15 check 6: payments.' || f || ' has search_path = empty') FROM rf;
SELECT is((SELECT pg_get_userbyid(proowner) FROM pg_proc WHERE pronamespace = 'payments'::regnamespace AND proname = f), 'lims_owner', 'C15 check 6: payments.' || f || ' owned by lims_owner (AC-0B-6.3)') FROM rf;
SELECT is((SELECT count(*)::int FROM pg_proc WHERE pronamespace = 'payments'::regnamespace), 2, 'C15 check 6: no function in payments beyond the 2 trigger guards (the DEFINER lives in schema app, CR-C15-004)');
SELECT is((SELECT count(*)::int FROM pg_proc WHERE pronamespace = 'app'::regnamespace AND proname = 'payments_resolve_callback_token' AND pg_get_function_identity_arguments(oid) = 'p_token_sha256 bytea'), 1, 'C15 check 6 / P-41: app.payments_resolve_callback_token(p_token_sha256 bytea) exists');
SELECT is((SELECT prosecdef FROM pg_proc WHERE oid = 'app.payments_resolve_callback_token(bytea)'::regprocedure), true, 'C15 check 6 / P-41: the callback lookup is SECURITY DEFINER');
SELECT is((SELECT proconfig FROM pg_proc WHERE oid = 'app.payments_resolve_callback_token(bytea)'::regprocedure), ARRAY['search_path=""'], 'C15 check 6 / REQ-SEC-020: DEFINER with search_path = empty');
SELECT is((SELECT pg_get_userbyid(proowner) FROM pg_proc WHERE oid = 'app.payments_resolve_callback_token(bytea)'::regprocedure), 'lims_owner', 'C15 check 6 / AC-0B-6.3: DEFINER owned by lims_owner');
SELECT is((SELECT provolatile FROM pg_proc WHERE oid = 'app.payments_resolve_callback_token(bytea)'::regprocedure), 'v', 'C15 check 6: the lookup is VOLATILE (it sets a GUC)');
SELECT is((SELECT proretset FROM pg_proc WHERE oid = 'app.payments_resolve_callback_token(bytea)'::regprocedure), true, 'C15 check 6: the lookup RETURNS TABLE (tenant_id, intent_id)');
SELECT is(has_function_privilege('lims_api', 'app.payments_resolve_callback_token(bytea)', 'EXECUTE'), true, 'C15 check 6 / P-41 (d): lims_api may EXECUTE the callback lookup');
SELECT is(has_function_privilege(r, 'app.payments_resolve_callback_token(bytea)', 'EXECUTE'), false, 'C15 check 6 / P-41 (d): ' || r || ' may NOT execute the callback lookup') FROM unnest(ARRAY['lims_app','lims_analytics']) r;
SELECT is((SELECT coalesce(proacl::text, '') ~ '(^\{|,)=X' FROM pg_proc WHERE oid = 'app.payments_resolve_callback_token(bytea)'::regprocedure), false, 'C15 check 6 / P-41: EXECUTE revoked from PUBLIC');

-- C15 check 7: FK direction, DEFINER inventory, no view, seeds (AC-0B-6.1 / 6.2 / 6.3; REQ-SEC-031)
SELECT is((SELECT array_agg(DISTINCT n.nspname::text ORDER BY n.nspname::text) FROM pg_constraint c JOIN pg_class r ON r.oid = c.confrelid JOIN pg_namespace n ON n.oid = r.relnamespace WHERE c.contype = 'f' AND c.conrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'payments'::regnamespace)),
  ARRAY['core','frontdesk','payments'], 'C15 check 7 / AC-0B-6.2: payments FKs point into payments, core, frontdesk only (01 §5 R3; none into billing, 02-CV §5.4)');
SELECT is((SELECT count(*)::int FROM pg_constraint c JOIN pg_class r ON r.oid = c.confrelid WHERE c.contype = 'f' AND r.relnamespace = 'payments'::regnamespace AND c.conrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace = 'payments'::regnamespace)), 0, 'C15 check 7 / AC-0B-6.2: nothing references payments from another schema');
SELECT is((SELECT count(*)::int FROM pg_proc WHERE pronamespace = 'payments'::regnamespace AND prosecdef), 0, 'C15 check 7: no SECURITY DEFINER function in schema payments');
SELECT is((SELECT count(*)::int FROM pg_proc WHERE prosecdef AND proname LIKE 'payments%'), 1, 'C15 check 7: exactly one DEFINER named payments_* (app.payments_resolve_callback_token), matching the inventory row');
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'payments'::regnamespace AND c.relkind = 'r' AND c.relname IN (SELECT t FROM rt)), 11, 'C15 check 7 / AC-0B-6.1: all 11 tenant tables exist after the migrations applied in order');
SELECT is((SELECT count(*)::int FROM payments.g_cs_reasons), 55, 'C15 check 7 / §5: 55 coded-set rows seeded');
SELECT is((SELECT array_agg(set_name || ':' || n ORDER BY set_name) FROM (SELECT set_name, count(*) n FROM payments.g_cs_reasons GROUP BY set_name) s),
  ARRAY['cancel_reasons:5','failure_reasons:4','finding_kinds:9','finding_resolutions:6','hold_reasons:11','refund_fail_reasons:3','refund_hold_reasons:3','refund_reasons:5','refund_reject_reasons:4','resolution_reasons:5'], 'C15 check 7 / §5: codes per set');
SELECT is((SELECT array_agg(set_name || '.' || code ORDER BY set_name, code) FROM payments.g_cs_reasons WHERE requires_text), ARRAY['cancel_reasons.other','finding_resolutions.other','refund_fail_reasons.other','refund_reasons.other','refund_reject_reasons.other','resolution_reasons.other'], 'C15 check 7 / §5: requires_text exactly on the "other" codes');
SELECT is((SELECT count(*)::int FROM payments.g_cs_reasons WHERE NOT is_active OR char_length(display) NOT BETWEEN 1 AND 120), 0, 'C15 check 7: seed rows active, display 1..120 chars');
SELECT is((SELECT count(*)::int FROM payments.settings) + (SELECT count(*)::int FROM payments.merchant_accounts) + (SELECT count(*)::int FROM payments.intents) + (SELECT count(*)::int FROM payments.cs_reasons), 0, 'C15 check 7 / §8: no tenant data seeded - settings are created lazily, no merchant secret in any seed (REQ-SEC-136)');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'storage' AND policyname LIKE 'payments%'), 0, 'C15 check 7: no storage policy is created by SQL');

SELECT * FROM finish();
ROLLBACK;
